// ⚙️ Program.cs - ORDER MATTERS!
var app = builder.Build();

// 1. Catches all crashes. Must be first!
app.UseExceptionHandler("/Error"); 

// 2. Returns images instantly without hitting controllers.
app.UseStaticFiles(); 

// 3. Checks WHO you are.
app.UseAuthentication(); 

// 4. Checks WHAT you are allowed to do.
app.UseAuthorization(); 

// 5. Actually runs your C# code.
app.MapControllers(); 

app.Run();


// 🚀 HOW TO WRITE CUSTOM MIDDLEWARE
app.Use(async (context, next) => {
    // --- THIS HAPPENS ON THE WAY IN ---
    Console.WriteLine("1. Request arrived!");

    // Pass the request to the next worker in line.
    // If you forget this line, the app freezes!
    await next(context); 

    // --- THIS HAPPENS ON THE WAY OUT ---
    Console.WriteLine("2. Response is leaving!");
});

