// ✅ ATTRIBUTE ROUTING (The Modern API Way)

[ApiController] // Tells ASP.NET this is an API
[Route("api/[controller]")] // Automatically uses the class name ("api/users")
public class UsersController : ControllerBase {

    // 1. Matches: GET /api/users
    [HttpGet]
    public IActionResult GetAll() {
        return Ok("All users");
    }

    // 2. Matches: GET /api/users/5
    // The {id} is extracted from the URL and passed to the method!
    [HttpGet("{id}")]
    public IActionResult GetById(int id) {
        return Ok($"User {id}");
    }

    // 3. Matches: POST /api/users
    [HttpPost]
    public IActionResult Create(User user) {
        return Created("", user);
    }
}

