// 🔒 CONTROLLER (Protecting the VIP Room)
[ApiController]
[Route("api/[controller]")]
public class SecretController : ControllerBase {

    [HttpGet]
    [Authorize] // 🛑 BOUNCER: Only people with valid JWTs can enter!
    public IActionResult GetSecretData() {
        // We can safely read data from the token payload!
        var userId = User.FindFirst(ClaimTypes.NameIdentifier)?.Value;
        return Ok($"Welcome to the VIP room, User {userId}");
    }
}

