var builder = WebApplication.CreateBuilder(args);

// 1. CREATE THE VIP GUEST LIST
builder.Services.AddCors(options => {
    options.AddPolicy("AllowMyFrontend", policy => {
        policy.WithOrigins("https://my-frontend-website.com") // Only this site!
              .AllowAnyHeader()
              .AllowAnyMethod(); // Allows GET, POST, PUT, etc.
    });
});

var app = builder.Build();

// 2. TELL THE BOUNCER TO USE THE LIST
// ⚠️ CRITICAL: Must be placed BEFORE UseAuthorization()
app.UseCors("AllowMyFrontend"); 

app.MapControllers();
app.Run();

// 1. CREATE THE FILTER
public class LogExecutionTimeFilter : IActionFilter {
    private Stopwatch _timer;

    // Runs right BEFORE the controller method
    public void OnActionExecuting(ActionExecutingContext context) {
        _timer = Stopwatch.StartNew();
    }

    // Runs right AFTER the controller method finishes
    public void OnActionExecuted(ActionExecutedContext context) {
        _timer.Stop();
        Console.WriteLine($"Method {context.ActionDescriptor.DisplayName} took {_timer.ElapsedMilliseconds} ms");
    }
}

// 2. ATTACH IT TO A SPECIFIC CONTROLLER METHOD
[ApiController]
[Route("api/[controller]")]
public class HeavyMathController : ControllerBase {

    // ✨ The filter will only wrap around this specific method!
    [ServiceFilter(typeof(LogExecutionTimeFilter))]
    [HttpGet("calculate")]
    public IActionResult DoHeavyMath() {
        Thread.Sleep(2000); // Simulate heavy work
        return Ok("Math done!");
    }
}

